int kvm_arch_complete_emulated_mmio(struct kvm_vcpu *vcpu) {
    struct kvm_run *run = vcpu->run;
    int ret = 0;

    if (!vcpu->mmio_needed)
        return 0;

    if (vcpu->mmio_is_write) {
        kvm_write_guest(vcpu->kvm, vcpu->mmio_phys_addr, vcpu->mmio_data, vcpu->mmio_data_len);
        run->exit_reason = KVM_EXIT_IO;
        run->io.direction = KVM_EXIT_IO_OUT;
        run->io.size = vcpu->mmio_data_len;
        run->io.count = 1;
        run->io.data = vcpu->mmio_data;
        ret = 1;
    } else {
        kvm_read_guest(vcpu->kvm, vcpu->mmio_phys_addr, vcpu->mmio_data, vcpu->mmio_data_len);
        run->exit_reason = KVM_EXIT_IO;
        run->io.direction = KVM_EXIT_IO_IN;
        run->io.size = vcpu->mmio_data_len;
        run->io.count = 1;
        run->io.data = vcpu->mmio_data;
    }

    vcpu->mmio_needed = 0;
    return ret;
}

int kvm_arch_vcpu_ioctl_run_mmio(struct kvm_vcpu *vcpu) {
    struct kvm_run *run = vcpu->run;
    struct kvm_mmio *mmio = &vcpu->mmio;
    gpa_t gpa;
    int ret;

    if (!mmio->data_valid)
        return 0;

    if (mmio->exit_reason == KVM_EXIT_MMIO) {
        gpa = mmio->gpa;
        if (mmio->is_write) {
            memcpy(mmio->data, &run->mmio.data, mmio->data_size);
            mmio->data_processed = true;
        } else {
            memcpy(&run->mmio.data, mmio->data, mmio->data_size);
            mmio->data_processed = true;
        }

        mmio->exit_reason = 0;
        return 1;
    }

    return 0;
}

int kvm_vcpu_exit_mmio(struct kvm_vcpu *vcpu) {
    struct kvm_run *run = vcpu->run;
    int ret = 0;

    if (!vcpu->mmio_needed)
        return 0;

    if (vcpu->mmio_is_write) {
        memcpy(vcpu->mmio_data, vcpu->mmio_fragment, vcpu->mmio_fragment_len);
        ret = 1;
    } else {
        memcpy(vcpu->mmio_fragment, vcpu->mmio_data, vcpu->mmio_fragment_len);
    }

    vcpu->mmio_fragment += vcpu->mmio_fragment_len;
    vcpu->mmio_remaining -= vcpu->mmio_fragment_len;

    if (vcpu->mmio_remaining == 0) {
        vcpu->mmio_needed = 0;
        vcpu->mmio_is_write = false;
        vcpu->mmio_data = NULL;
        vcpu->mmio_fragment = NULL;
        vcpu->mmio_remaining = 0;
    }

    run->exit_reason = KVM_EXIT_MMIO;
    run->mmio.phys_addr = vcpu->mmio_phys_addr;
    run->mmio.is_write = vcpu->mmio_is_write;
    run->mmio.data_size = vcpu->mmio_data_len;
    memcpy(run->mmio.data, vcpu->mmio_data, vcpu->mmio_data_len);

    return ret;
}

int kvm_vcpu_mmio_complete(struct kvm_vcpu *vcpu) {
    struct kvm_run *run = vcpu->run;
    int ret = 0;

    if (!vcpu->mmio_needed)
        return 0;

    if (vcpu->mmio_is_write) {
        memcpy(vcpu->mmio_data, vcpu->mmio_fragment, vcpu->mmio_fragment_size);
        vcpu->mmio_data += vcpu->mmio_fragment_size;
        vcpu->mmio_size -= vcpu->mmio_fragment_size;

        if (!vcpu->mmio_size) {
            vcpu->mmio_needed = 0;
            vcpu->mmio_is_write = 0;
            vcpu->mmio_data = NULL;
            ret = 1;
        }
    } else {
        memcpy(vcpu->mmio_fragment, vcpu->mmio_data, vcpu->mmio_fragment_size);
        vcpu->mmio_data += vcpu->mmio_fragment_size;
        vcpu->mmio_size -= vcpu->mmio_fragment_size;

        if (!vcpu->mmio_size) {
            vcpu->mmio_needed = 0;
            vcpu->mmio_is_write = 0;
            vcpu->mmio_data = NULL;
            ret = 1;
        }
    }

    run->exit_reason = KVM_EXIT_MMIO;
    run->mmio.is_write = vcpu->mmio_is_write;
    run->mmio.phys_addr = vcpu->mmio_phys_addr;
    run->mmio.len = vcpu->mmio_fragment_size;
    if (vcpu->mmio_is_write)
        memcpy(&run->mmio.data, vcpu->mmio_fragment, vcpu->mmio_fragment_size);
    else
        memcpy(vcpu->mmio_fragment, &run->mmio.data, vcpu->mmio_fragment_size);

    return ret;
}

int kvm_arch_complete_mmio(struct kvm_vcpu *vcpu) {
    int ret = 0;
    gpa_t gpa;
    int len;
    struct kvm_run *run = vcpu->run;

    if (!vcpu->mmio_needed)
        return 0;

    gpa = vcpu->mmio_phys_addr;
    len = vcpu->mmio_data_len;

    if (vcpu->mmio_is_write)
        kvm_write_guest_phys(vcpu->kvm, gpa, vcpu->mmio_data, len);
    else
        kvm_read_guest_phys(vcpu->kvm, gpa, vcpu->mmio_data, len);

    run->exit_reason = KVM_EXIT_MMIO;
    run->mmio.phys_addr = gpa;
    run->mmio.len = len;
    run->mmio.is_write = vcpu->mmio_is_write;
    memcpy(&run->mmio.data, vcpu->mmio_data, len);

    vcpu->mmio_needed = 0;
    ret = vcpu->mmio_is_write ? 1 : 0;

    return ret;
}
